import {validate} from '../document/validate.js';
const request=r=>new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});
export class Store{async open(){const r=indexedDB.open('poppy-animator',1);r.onupgradeneeded=()=>{r.result.createObjectStore('projects',{keyPath:'id'});r.result.createObjectStore('assets');r.result.createObjectStore('meta');};this.db=await request(r);return this;}
async transaction(names,fn){const t=this.db.transaction(names,'readwrite');const done=new Promise((ok,no)=>{t.oncomplete=ok;t.onerror=()=>no(t.error);t.onabort=()=>no(t.error||Error('Save interrupted'));});fn(t);await done;}
async save(p,assets){await this.transaction(['projects','assets','meta'],t=>{t.objectStore('projects').put({...structuredClone(p),savedAt:Date.now()});t.objectStore('meta').put(p.id,'last');if(p.audio){const blob=assets.get(p.audio.assetId);if(blob)t.objectStore('assets').put(blob,p.audio.assetId);}});}
async last(){const id=await request(this.db.transaction('meta').objectStore('meta').get('last'));return id?this.load(id):null;}
async load(id){const p=await request(this.db.transaction('projects').objectStore('projects').get(id));if(!p)return null;validate(p);const assets=new Map();if(p.audio){const blob=await request(this.db.transaction('assets').objectStore('assets').get(p.audio.assetId));if(!blob)throw Error('The project’s audio asset is missing.');assets.set(p.audio.assetId,blob);}return {project:p,assets};}
async list(){return request(this.db.transaction('projects').objectStore('projects').getAll());}}
export function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
export async function portable(p,assets){const result={format:'poppy-project',project:p,assets:{}};if(p.audio){const blob=assets.get(p.audio.assetId);if(!blob)throw Error('Audio asset is missing.');result.assets[p.audio.assetId]=await new Promise((ok,no)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=no;reader.readAsDataURL(blob);});}return new Blob([JSON.stringify(result)],{type:'application/json'});}
export async function importPortable(file){if(file.size>200*1024*1024)throw Error('Project file exceeds 200 MB.');const data=JSON.parse(await file.text());if(data.format!=='poppy-project')throw Error('Choose a .poppy project file.');const p=validate(data.project),assets=new Map();if(p.audio){const encoded=data.assets?.[p.audio.assetId];if(typeof encoded!=='string'||!/^data:audio\/[a-z0-9.+-]+(;[^,]*)?;base64,/i.test(encoded))throw Error('Invalid or missing audio asset.');const blob=await (await fetch(encoded)).blob();assets.set(p.audio.assetId,blob);}return {project:p,assets};}
